.container{max-width:var(--container);padding:0 var(--gutter);margin:0 auto}
section{padding:var(--section-y) 0}
.dark{background:var(--dark);color:#bdb3a2}.dark h2{color:#fff}
h1,h2,h3{font-family:'Cormorant Garamond',serif;font-weight:500;color:var(--ink);line-height:1.12}
