h3{font-size:20px;font-family:'Inter',sans-serif;font-weight:500}
.label{font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:#9a917f;text-align:center}.label::before{content:'• '}
.btn{display:inline-flex;align-items:center;gap:8px;height:40px;padding:0 22px;border-radius:99px;background:var(--dark);color:#fff;font-size:11px}
.card{background:var(--card);border:1px solid var(--line);border-radius:var(--radius);overflow:hidden}
.wordmark{font-size:120px;font-weight:600;letter-spacing:-.02em;color:#fff;line-height:1}
